#include "blocks_synth.h"
#include "blocks_osc_bass.h"
#include "blocks_bass_support.h"
#include <array>
#include <fstream>
#include <string>
#include <cmath>
#include <cstdio>
#include <algorithm>
static void put(std::ostream&o,uint32_t v,unsigned n){for(unsigned i=0;i<n;++i)o.put(char(v>>(i*8)));}
int main(int argc,char**argv){if(argc!=2)return 1;constexpr unsigned frames=48000*4;const char*names[]={"rotor","growl","throat","fray","fray-clean-sub","fray-fx-sub"};for(unsigned mode=0;mode<6;++mode){auto*s=bs_create();if(!s||!bs_prepare(s,48000))return 2;bs_set_parameter(s,BS_OSC1_WAVE,BS_SAW);bs_set_parameter(s,BS_OSC1_LEVEL,.7f);bs_set_parameter(s,BS_OSC2_LEVEL,0);bs_set_parameter(s,BS_GAIN,.3f);bs_set_parameter(s,BS_DRIVE_ENABLED,0);bs_set_parameter(s,BS_FULLNESS_ENABLED,0);bs_set_parameter(s,BS_PITCH_DROP_ENABLED,0);bs_set_parameter(s,BS_FILTER_MIX,0);bs_set_parameter(s,BS_ATTACK,.005f);bs_set_parameter(s,BS_DECAY,.25f);bs_set_parameter(s,BS_SUSTAIN_LEVEL,.5f);bs_set_parameter(s,BS_RELEASE,.1f);bs_clock_config clock{1,120,4};bs_set_clock(s,&clock);bs_osc_bass_config_v2 bass{};bs_default_osc_bass_v2(&bass);bass.oscillators[0]={1,std::min(mode,3u),1,0,4,.85f,.75f,.5f,.5f};bs_set_osc_bass_v2(s,&bass);bs_sub_config sub{};bs_default_sub(&sub);sub.enabled=mode>=4;sub.level=.5f;sub.routing=mode==5;bs_set_sub(s,&sub);bs_reset(s);std::string file=std::string(argv[1])+"/"+names[mode]+".wav";std::ofstream out(file,std::ios::binary);if(!out)return 3;out.write("RIFF",4);put(out,36+frames*4,4);out.write("WAVEfmt ",8);put(out,16,4);put(out,1,2);put(out,2,2);put(out,48000,4);put(out,192000,4);put(out,4,2);put(out,16,2);out.write("data",4);put(out,frames*4,4);std::array<float,128>l{},r{};double peak=0,squares=0;const unsigned keys[]={36,43,38,41};const float velocities[]={.85f,.55f,.95f,.65f};for(unsigned start=0;start<frames;start+=128){const unsigned n=std::min(128u,frames-start);std::array<bs_event,8>events{};unsigned count=0;for(unsigned note=0;note<4;++note){const unsigned on=note*48000,off=on+36000;if(on>=start&&on<start+n)events[count++]={on-start,BS_NOTE_ON,0,keys[note],0,velocities[note]};if(off>=start&&off<start+n)events[count++]={off-start,BS_NOTE_OFF,0,keys[note],0,0};}if(bs_render(s,l.data(),r.data(),n,events.data(),count))return 4;for(unsigned i=0;i<n;++i)for(float x:{l[i],r[i]}){if(!std::isfinite(x)||std::abs(x)>=1)return 5;peak=std::max(peak,std::abs(double(x)));squares+=x*x;put(out,uint16_t(int16_t(std::lround(x*32767))),2);}}std::printf("%s peak=%.9g RMS=%.9g noNormalization gain=.3 level1=.7\n",file.c_str(),peak,std::sqrt(squares/(frames*2)));bs_destroy(s);}return 0;}
